package studio.jiayu.neoagent;
import android.content.pm.ApplicationInfo;import android.os.SystemClock;import org.json.*;import org.vosk.*;import java.io.*;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;

/** Actual on-device Vosk decode -> unchanged final text -> production chat; never uses microphone. */
final class VoicePcmChatContracts {
 static final String REPORT="voice-pcm-chat-entry.json",MODEL_SHA256="3af8b0e7e0f835ae9d414ce5df580237a3cfb08d586c9fbbb0f7ff29ad5b14ba";
 final UiQaActivity a;final JSONObject report=new JSONObject();final ArrayList<String> finalTexts=new ArrayList<>();final JSONArray rawResults=new JSONArray();final long began=SystemClock.elapsedRealtime();
 OfflineVoice previous,controller;String session="",request="",stage="precondition";long turn,lease;boolean installed,submitted;
 VoicePcmChatContracts(UiQaActivity owner){a=owner;}
 static void start(UiQaActivity a){new VoicePcmChatContracts(a).begin();}
 void begin(){try{
  report.put("source","public synthetic PCM decoded on-device by bundled Vosk; not microphone").put("microphone_used",false).put("microphone_permission_requested",false).put("audio_uploaded",false).put("input_file","qa-voice-input.pcm").put("expected_pcm_sha256",VoicePcmRules.PCM_SHA256).put("sampleRate",16000).put("format","mono PCM16LE").put("manual_correction",false).put("lexical_correction",false).put("formatting","production VoiceSession.normalize only; no word replacement").put("correct_reference_in_planner",false).put("fake_provider_installed",false).put("submitted_to_chat",false).put("task_completion_proven",false).put("real_microphone_acceptance",false);
  require((a.getApplicationInfo().flags&ApplicationInfo.FLAG_DEBUGGABLE)!=0,"not_debug");ControlService runtime=ControlService.instance;require(runtime!=null&&runtime.connected&&!runtime.busy()&&!a.planning,"runtime_not_idle");require(a.resumed&&a.loaded&&"pcm".equals(a.voiceMode())&&!a.voiceUiTest(),"pcm_ui_not_ready");previous=a.voice;require(previous==null||!previous.active(),"other_voice_active");
  a.newChat();require(a.chat()!=null,"chat_unavailable");a.chat().put("title","调试 · PCM端侧识别与执行");a.saveChats();session=a.sessionId;request=a.beginVoiceRequest();turn=a.turn;
  controller=new OfflineVoice(a,new OfflineVoice.Listener(){public boolean foreground(){return a.resumed&&!a.isFinishing();}public void state(JSONObject value){try{value.put("request",request);}catch(Exception ignored){}a.event("voice",value);}public void result(String text,boolean direct){a.voiceResult(text,direct);}public void error(String message){a.event("notice",message);}});a.voice=controller;installed=true;lease=controller.session.begin(true);require(lease>0,"voice_lease_unavailable");a.voiceOwnerSession=session;
  report.put("memory_namespace",a.memoryKey()).put("chat_storage","test-voice-chats").put("session_bound",true);stage="validating_audio_model";persist();a.event("voice",OfflineVoice.state("preparing","正在解码公开合成PCM，未读取麦克风；可取消",0).put("request",request));new Thread(this::decode,"qa-voice-pcm-final").start();
 }catch(Throwable failed){failure(failed);cleanup();}}
 void decode(){try{
  File input=new File(a.getFilesDir(),"qa-voice-input.pcm");require(input.isFile()&&input.length()==VoicePcmRules.PCM_BYTES,"pcm_missing_or_size_mismatch");byte[] pcm=Files.readAllBytes(input.toPath());String sha=digest(new ByteArrayInputStream(pcm));report.put("pcm_sha256",sha).put("pcm_bytes",pcm.length);require(VoicePcmRules.input(pcm.length,sha),"pcm_sha256_mismatch");report.put("input_verified",true);current();
  stage="validating_model";String archive=digest(a.getAssets().open(OfflineVoice.ASSET));report.put("model_asset_sha256",archive);require(MODEL_SHA256.equals(archive),"model_archive_sha256_mismatch");File model=OfflineVoice.unpack(a);int checked=validateModel(model);report.put("model_files_verified",checked).put("model_verified",true);current();
  stage="decoding";try(Model nativeModel=new Model(model.getAbsolutePath());Recognizer recognizer=new Recognizer(nativeModel,OfflineVoice.RATE)){
   report.put("model_ready",true);for(int start=0;start<pcm.length;start+=6400){current();int length=Math.min(6400,pcm.length-start);byte[] frame=Arrays.copyOfRange(pcm,start,start+length);if(recognizer.acceptWaveForm(frame,length))accept(recognizer.getResult());}accept(recognizer.getFinalResult());
  }
  report.put("native_decode_resources_released",true);String raw=VoicePcmRules.joinRaw(finalTexts);require(!raw.trim().isEmpty()&&raw.length()<=6000,"empty_or_oversize_final");report.put("raw_results",rawResults).put("raw_transcript",raw).put("segment_joiner","single ASCII space between nonempty final segments").put("decode_verified",true);stage="decoded_final_not_submitted";persist();a.runOnUiThread(()->deliver(raw));
 }catch(Throwable failed){a.runOnUiThread(()->{failure(failed);cleanup();});}}
 void accept(String json)throws Exception{JSONObject result=new JSONObject(json);rawResults.put(result);String text=result.optString("text");if(!text.trim().isEmpty())finalTexts.add(text);}
 void current()throws Exception{require(controller!=null&&controller.session.current(lease),"cancelled_or_replaced");}
 void deliver(String raw){try{
  boolean foreground=a.resumed&&!a.isFinishing();boolean valid=VoicePcmRules.deliver(session,a.sessionId,turn,a.turn,a.voiceMode(),foreground,a.voice==controller,controller.session.current(lease),raw)&&session.equals(a.voiceOwnerSession);
  if(!valid){stage="cancelled_before_submission";report.put("delivery_rejected",true).put("success",false);persist();return;}
  controller.session.segment(lease,raw);VoiceSession.Result finalGuard=controller.session.finish(lease,true);require(finalGuard!=null&&finalGuard.direct,"final_guard_rejected");
  // Match production capture exactly: only VoiceSession.normalize formatting, never lexical correction.
  String delivered=finalGuard.text;a.event("voice",OfflineVoice.state("idle","",0).put("request",request));long before=a.turn;a.voiceResult(delivered,true);boolean accepted=a.turn!=before;submitted=accepted;stage=accepted?"submitted_to_original_chat":"chat_rejected";report.put("submitted_to_chat",accepted).put("submitted_text",delivered).put("submitted_text_sha256",digest(new ByteArrayInputStream(delivered.getBytes("UTF-8")))).put("submitted_equals_raw",delivered.equals(raw)).put("submitted_equals_normalized_raw",delivered.equals(VoiceSession.normalize(raw))).put("success",accepted).put("success_meaning","synchronous final submission accepted by original chat planning entry; not task completion").put("pipeline","app-private PCM -> bundled Vosk -> production-formatted final (no lexical correction) -> MainActivity.voiceResult -> original sendMessage/planner/executor");persist();
 }catch(Throwable failed){failure(failed);}finally{cleanup();}}
 int validateModel(File model)throws Exception{int files=0;try(ZipInputStream zip=new ZipInputStream(a.getAssets().open(OfflineVoice.ASSET))){ZipEntry entry;byte[] buffer=new byte[32768];while((entry=zip.getNextEntry())!=null){current();if(entry.isDirectory())continue;require(entry.getName().startsWith(OfflineVoice.MODEL+"/"),"invalid_model_entry");String name=entry.getName().substring(OfflineVoice.MODEL.length()+1);File target=new File(model,name);require(target.getCanonicalPath().startsWith(model.getCanonicalPath()+File.separator)&&target.isFile(),"model_file_missing");MessageDigest expected=MessageDigest.getInstance("SHA-256");long size=0;int n;while((n=zip.read(buffer))!=-1){expected.update(buffer,0,n);size+=n;}require(target.length()==size&&hex(expected.digest()).equals(digest(new FileInputStream(target))),"model_file_integrity_mismatch");files++;zip.closeEntry();}}require(files>5,"model_file_inventory_incomplete");return files;}
 static String digest(InputStream input)throws Exception{try(InputStream source=input){MessageDigest sha=MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[32768];int n;while((n=source.read(buffer))!=-1)sha.update(buffer,0,n);return hex(sha.digest());}}
 static String hex(byte[] bytes){StringBuilder text=new StringBuilder();for(byte value:bytes)text.append(String.format(java.util.Locale.ROOT,"%02x",value&255));return text.toString();}
 static void require(boolean value,String code)throws Exception{if(!value)throw new FixtureFailure(code);}
 static final class FixtureFailure extends Exception{FixtureFailure(String code){super(code);}}
 void failure(Throwable failed){try{report.put("success",false).put("failure_stage",stage).put("failure_type",failed.getClass().getSimpleName()).put("failure_code",failed instanceof FixtureFailure?failed.getMessage():"native_or_io_failure").put("submitted_to_chat",submitted);stage=submitted?"diagnostic_failed_after_submission":"failed_before_submission";persist();}catch(Exception ignored){}}
 void persist()throws Exception{report.put("stage",stage).put("elapsedMs",SystemClock.elapsedRealtime()-began).put("sampledAt",System.currentTimeMillis());try(FileOutputStream out=a.openFileOutput(REPORT,0)){out.write(report.toString(2).getBytes("UTF-8"));out.getFD().sync();}}
 void cleanup(){if(!installed||a.voice!=controller)return;if(controller.active()&&!controller.session.current(lease))return;controller.cancel();controller.close();a.voice=previous;installed=false;}
}
